package com.project7.localmanager;
import android.content.*;import android.content.res.*;import android.system.Os;import java.io.*;import java.nio.file.*;import java.util.*;
/** Source-bound voucher policy uses the actual stock memory runner, never draw apply/saveState. */
public final class BaiyeFragmentHost {
 static final String NAMED="requestExchangeSuipianWithItem",SELECT="invExchangeHeroFragmentAsk";
 static void check(boolean v,String s){BaiyeHost.check(v,s);}
 static byte[]p(int item,int n,int hero,int mask){byte[]base=BaiyeHost.profile(0,0);base=BsonLite.withProfileDocument(base,"inv",BsonLite.document("items",Arrays.asList(BaiyeHost.item(item,n),BaiyeHost.item(24,999)),"opaque","preserve"));return BsonLite.withProfileDocument(base,"ldd",BsonLite.document("hfp",BsonLite.document(Integer.toString(hero),mask),"ct",6,"q7File",BsonLite.document("sentinel",true),"ad",Arrays.asList(Arrays.asList(485,BsonLite.document("ct",12))),"opaque","preserve"));}
 static List<ProtoLite.EntityMessage>call(BaiyeHost.Disk d,String name,byte[]params)throws Exception{ByteArrayOutputStream out=new ByteArrayOutputStream();check(BaiyeGateway.handleDirect(d.g,out,BaiyeHost.EID,BaiyeGateway.digest(name),params,BaiyeHost.ACCOUNT,null,null),"fragment handled");return BaiyeHost.frames(out.toByteArray());}
 static byte[]named(int item,int hero,int piece){return BsonLite.document("ii",item,"hi",hero,"fn",piece,"_cbid_",7);}
 static byte[]select(int item,int hero,int piece){return BsonLite.document("i",item,"h",hero,"s",piece);}
 static byte[]reply(List<ProtoLite.EntityMessage>r,String method){for(ProtoLite.EntityMessage m:r)if(Arrays.equals(m.methodMd5,BaiyeGateway.digest(method)))return m.parameters;throw new AssertionError("Missing "+method);}
 static int mask(byte[]profile,int hero){return BsonLite.intValue(BsonLite.documentValue(BsonLite.documentValue(profile,"ldd"),"hfp"),Integer.toString(hero));}
 static void preserved(byte[]profile){byte[]ldd=BsonLite.documentValue(profile,"ldd");check(BsonLite.intValue(ldd,"ct")==6&&Boolean.TRUE.equals(BsonLite.boolValue(BsonLite.documentValue(ldd,"q7File"),"sentinel")),"no draw ct/file side effects");check("preserve".equals(BsonLite.stringValue(ldd,"opaque")),"unknown ldd preserved");check(BaiyeTransactions.count(profile,24)==999,"voucher-one policy never extra24 charge");}
 static void fail(BaiyeHost.Disk d,String method,byte[]params)throws Exception{byte[]before=d.read();List<ProtoLite.EntityMessage>r=call(d,method,params);byte[]reply=reply(r,method.equals(NAMED)?"replyExchangeSuipianWithItem":"invExchangeHeroFragmentReply");check(Boolean.FALSE.equals(BsonLite.boolValue(reply,method.equals(NAMED)?"rs":"r")),"typed negative");check(Arrays.equals(before,d.read()),"negative no profile change");}
 public static void main(String[]args)throws Exception{
  File assets=new File(args[0]);Context c=new Context(assets,new AssetManager(assets));CoreDrawPolicy.prepare(c);HistoryDrawPolicy.prepare(c);SelectorPolicy.prepare(c);OfflineMechanismGateway.prepare(c);BaiyeGateway.prepare(c);Map<String,Object>cases=new LinkedHashMap<>();
  try(BaiyeHost.Disk d=new BaiyeHost.Disk(assets,p(10126,3,13,0))){List<ProtoLite.EntityMessage>first=call(d,NAMED,named(10126,13,1));BaiyeHost.callback(first);check(mask(d.read(),13)==1&&!LocalResourceEngine.ownsHero(d.read(),13)&&BaiyeTransactions.count(d.read(),4255)==0,"new partial only original hfp, no invented crystal");check(BaiyeTransactions.count(d.read(),10126)==2,"one named voucher consumed");preserved(d.read());cases.put("named_partial",BsonLite.messagePackValue(reply(first,"replyExchangeSuipianWithItem"),false));cases.put("named_callback",BsonLite.messagePackValue(first.get(first.size()-1).parameters,false));cases.put("prog",BsonLite.messagePackValue(reply(first,"syncProgInfo"),false));
   List<ProtoLite.EntityMessage>dup=call(d,NAMED,named(10126,13,1));check(mask(d.read(),13)==1&&BaiyeTransactions.count(d.read(),4255)==1,"duplicate original crystal exactly one");cases.put("named_duplicate",BsonLite.messagePackValue(reply(dup,"replyExchangeSuipianWithItem"),false));
   List<ProtoLite.EntityMessage>last=call(d,NAMED,named(10126,13,2));check(mask(d.read(),13)==3&&LocalResourceEngine.ownsHero(d.read(),13)&&BaiyeTransactions.count(d.read(),4255)==1,"last bit grants actual hero no extra crystal");preserved(d.read());cases.put("named_hero",BsonLite.messagePackValue(reply(last,"replyExchangeSuipianWithItem"),false));
  }
  try(BaiyeHost.Disk d=new BaiyeHost.Disk(assets,p(10126,2,13,0))){fail(d,NAMED,named(10126,13,0));fail(d,NAMED,named(10126,80,1));fail(d,NAMED,named(10126,13,3));Os.failBefore=true;fail(d,NAMED,named(10126,13,1));}
  LocalResourceCatalog resources=new LocalResourceCatalog(new FileInputStream(new File(assets,"resources.tsv")));
  {LocalResourceEngine.Result owned=new LocalResourceEngine.Result(p(10126,1,13,3));LocalResourceEngine.grant(owned,resources,"hero",13,1,1);try(BaiyeHost.Disk d=new BaiyeHost.Disk(assets,owned.profile)){List<ProtoLite.EntityMessage>r=call(d,NAMED,named(10126,13,0));check(BaiyeTransactions.count(d.read(),4255)==1,"owned fn0 one crystal not duplicateHero multiplier");cases.put("named_zero",BsonLite.messagePackValue(reply(r,"replyExchangeSuipianWithItem"),false));}}
  try(BaiyeHost.Disk d=new BaiyeHost.Disk(assets,p(10954,1,13,0))){List<ProtoLite.EntityMessage>r=call(d,SELECT,select(10954,13,1));for(ProtoLite.EntityMessage m:r)check(!Arrays.equals(m.methodMd5,BaiyeGateway.digest("serverCallbackCarrier")),"original inv no callback gets no carrier");check(mask(d.read(),13)==1&&BaiyeTransactions.count(d.read(),10954)==0,"select voucher real progress");preserved(d.read());cases.put("select_partial",BsonLite.messagePackValue(reply(r,"invExchangeHeroFragmentReply"),false));}
  try(BaiyeHost.Disk d=new BaiyeHost.Disk(assets,p(10954,1,13,0))){fail(d,SELECT,select(10954,80,1));fail(d,SELECT,select(10954,13,0));Os.failBefore=true;fail(d,SELECT,select(10954,13,1));Os.failAfter=true;List<ProtoLite.EntityMessage>r=call(d,SELECT,select(10954,13,1));check(Boolean.TRUE.equals(BsonLite.boolValue(reply(r,"invExchangeHeroFragmentReply"),"r"))&&mask(d.read(),13)==1,"fragment afterrename exact image committed");}
  try(BaiyeHost.Disk d=new BaiyeHost.Disk(assets,p(10135,1,80,0))){List<ProtoLite.EntityMessage>r=call(d,SELECT,select(10135,80,1));check(mask(d.read(),80)==1,"fixed voucher absent from resources can consume existing real owned inventory, no fabricated source grant");}
  cases.put("named_failure",BsonLite.messagePackValue(BaiyeGateway.failure(NAMED,"fixture",0).replies.get(1).parameters,false));cases.put("select_failure",BsonLite.messagePackValue(BaiyeGateway.failure(SELECT,"fixture",0).replies.get(1).parameters,false));
  Files.write(Paths.get(args[1]),new org.json.JSONObject(cases).toString(2).getBytes("UTF-8"));System.out.println("PASS real stock memory partial/duplicate/last/owned conversion; source eligibility, one-voucher/no24, hfp sync, original atomic faults, no draw state mutation");
 }
}
